def link(path,txt,cls='',external=False):
 return f'<a class="{cls}" href="{escape(path)}"'+(' target="_blank" rel="noopener noreferrer"' if external else '')+f'>{escape(txt)}</a>'

def gridcard(icon,title,desc,url,label='Conocer más'):
 return f'<article class="product-card"><div class="product-icon">{icon}</div><h3>{escape(title)}</h3><p>{escape(desc)}</p>{link(url,label,'arrow-link')}<span aria-hidden="true" class="corner-dot"></span></article>'

def grid(cards):return '<div class="card-grid">'+''.join(cards)+'</div>'

def hero(eyebrow,title,sub,action='Solicitar crédito',target='/solicitud-de-credito-tu-credito/'):
 return f'<section class="page-hero"><div class="container"><div class="eyebrow">{escape(eyebrow)}</div><h1>{escape(title)}</h1><p>{escape(sub)}</p><div class="page-hero-actions">{link(target,action+' ↗','button button-yellow')} {link('/contactenos/','Hablar con nosotros','button button-ghost')}</div></div></section>'

def block(title,body,eyebrow='',extra=''):
 return f'<section class="section"><div class="container"><div class="section-heading">{f"<span class=\'kicker\'>{escape(eyebrow)}</span>" if eyebrow else ""}<h2>{escape(title)}</h2></div>{body}{extra}</div></section>'

def columns(items):
 return '<div class="two-cols">'+''.join(f'<div class="white-panel"><h3>{escape(t)}</h3><p>{esc_paragraphs(b)}</p></div>' for t,b in items)+'</div>'

def esc_paragraphs(s):return escape(s).replace('\n','<br>')

def facts(items):return '<ul class="feature-list">'+''.join(f'<li><span class="check">✓</span>{escape(x)}</li>' for x in items)+'</ul>'

def source_note(path):
 return f'<p class="source-note">Información resumida del portal institucional. Verificá las condiciones vigentes en {link(ORIG+path,"el contenido publicado",external=True)}.</p>'

def actions(cta='Iniciar una solicitud',target='/solicitud-de-credito-tu-credito/'):
 return f'<div class="action-banner"><div><small>¿TENÉS ALGUNA CONSULTA?</small><h2>Estamos para orientarte</h2><p>Conocé los canales de atención y consultá las condiciones vigentes antes de solicitar.</p></div>{link(target,cta+' ↗','button button-yellow')}</div>'

