import urllib.parse
BRANCHES=json.loads((ROOT/'data/sucursales.json').read_text('utf8'))
# Mantener sincronizada la base del chatbot con la fuente única de sucursales.
(SRC/'sucursales.ts').write_text('export const sucursales = '+json.dumps([{'slug':b['slug'],'name':b['name'],'address':b['address'],'whatsapp':b['wa'],'phone':b['phone'],'source':b['source']} for b in BRANCHES],ensure_ascii=False,indent=2)+' as const;\n',encoding='utf8')
def branch_link(b): return f'/sucursales/{b["slug"]}/'
def maplink(b):return 'https://www.google.com/maps/search/?api=1&query='+urllib.parse.quote_plus('Tu Crédito '+b['office']+' '+b['address']+' Nicaragua')
def card_branch(b):
  return (f'<a class="v6-directory-card" href="{branch_link(b)}"><img src="/assets/sucursal-{b["slug"]}-referencia.webp" alt="Imagen de referencia del boceto para {escape(b["name"])}" width="720" height="420" loading="eager"><div><span>⌖ SUCURSAL</span><h3>{escape(b["name"])}</h3><p>{escape(b["address"])}</p><strong>Ver sucursal y contacto →</strong></div></a>')
